module hipfort_hipblas
  use hipfort_hipblas_enums
  use hipfort_hipblas_types
  use, intrinsic :: iso_c_binding
  implicit none

  !--- Opaque handles (all are typedef struct* → type(c_ptr)) ---
  !    hipblasHandle_t

  !--- 1199 bind(C) interfaces ---
  interface

    !---------------------------------------------
    ! hipblasCreate
    !---------------------------------------------
    !> \brief Create the hipBLAS handle.
    function hipblasCreate(handle) &
       result(Create) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasCreate_v2")
#else
       bind(C, name="hipblasCreate")
#endif
       import :: c_ptr, c_int
       type(c_ptr) :: handle
       integer(c_int) :: Create
    end function hipblasCreate

    !---------------------------------------------
    ! hipblasDestroy
    !---------------------------------------------
    !> \brief Destroys the library context created using hipblasCreate().
    function hipblasDestroy(handle) &
       result(Destroy) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasDestroy_v2")
#else
       bind(C, name="hipblasDestroy")
#endif
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int) :: Destroy
    end function hipblasDestroy

    !---------------------------------------------
    ! hipblasGetVersion
    !---------------------------------------------
    !> \brief Gets the hipBLAS library version number.
    !> \details
    !> Returns version as integer: major * 10000 + minor * 100 + patch.
    !> Example: version 3.5.1 returns 30501.
    !>
    !> Handle parameter can be NULL.
    !>
    !> @param[in]  handle    Handle to library context (can be NULL)
    !> @param[out] version   Pointer to integer for version number
    !>
    !> @return HIPBLAS_STATUS_SUCCESS or HIPBLAS_STATUS_INVALID_VALUE if version is NULL
    function hipblasGetVersion(handle, version) &
       result(GetVersion) &
       bind(C, name="hipblasGetVersion")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int) :: version(*)
       integer(c_int) :: GetVersion
    end function hipblasGetVersion

    !---------------------------------------------
    ! hipblasGetProperty
    !---------------------------------------------
    !> \brief Gets a specific property of the hipBLAS library.
    !> \details
    !> Returns requested property value (major, minor, or patch).
    !> Does not require a handle.
    !>
    !> @param[in]  type     Property type to query
    !> @param[out] value    Pointer to integer for property value
    !>
    !> @return HIPBLAS_STATUS_SUCCESS or HIPBLAS_STATUS_INVALID_VALUE
    function hipblasGetProperty(type, value) &
       result(GetProperty) &
       bind(C, name="hipblasGetProperty")
       import :: c_int
       integer(c_int), value :: type
       integer(c_int) :: value(*)
       integer(c_int) :: GetProperty
    end function hipblasGetProperty

    !---------------------------------------------
    ! hipblasSetStream
    !---------------------------------------------
    !> \brief Sets the stream for the handle
    function hipblasSetStream(handle, streamId) &
       result(SetStream) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasSetStream_v2")
#else
       bind(C, name="hipblasSetStream")
#endif
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr), value :: streamId
       integer(c_int) :: SetStream
    end function hipblasSetStream

    !---------------------------------------------
    ! hipblasGetStream
    !---------------------------------------------
    !> \brief Gets stream[0] for the handle
    function hipblasGetStream(handle, streamId) &
       result(GetStream) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasGetStream_v2")
#else
       bind(C, name="hipblasGetStream")
#endif
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr) :: streamId
       integer(c_int) :: GetStream
    end function hipblasGetStream

