    !---------------------------------------------
    ! hipblasSgeam
    !---------------------------------------------
    !> \brief  BLAS Level 3 API
    !>
    !> \details
    !> The geam functions perform one of the matrix-matrix operations:
    !>
    !> C = alpha*op( A ) + beta*op( B ),
    !>
    !> where op( X ) is one of
    !>
    !> op( X ) = X      or
    !> op( X ) = X**T   or
    !> op( X ) = X**H,
    !>
    !> ``alpha`` and ``beta`` are scalars, and ``A``, ``B`` and ``C`` are matrices, with
    !> ``op( A )`` an ``m`` by ``n`` matrix, ``op( B )`` an ``m`` by`` n`` matrix, and ``C`` an
    !> ``m`` by ``n`` matrix.
    !>
    !> - Supported precisions in rocBLAS : ``s``, ``d``, ``c``, and ``z``.
    !> - Supported precisions in cuBLAS  : ``s``, ``d``, ``c``, and ``z``.
    !>
    !> @param[in]
    !> handle    [hipblasHandle_t]
    !> handle to the hipBLAS library context queue.
    !> @param[in]
    !> transA    [hipblasOperation_t]
    !> specifies the form of op( A ).
    !> @param[in]
    !> transB    [hipblasOperation_t]
    !> specifies the form of op( B ).
    !> @param[in]
    !> m         [int]
    !> matrix dimension m.
    !> @param[in]
    !> n         [int]
    !> matrix dimension n.
    !> @param[in]
    !> alpha     device pointer or host pointer specifying the scalar alpha.
    !> @param[in]
    !> AP         device pointer storing matrix A.
    !> @param[in]
    !> lda       [int]
    !> specifies the leading dimension of A.
    !> @param[in]
    !> beta      device pointer or host pointer specifying the scalar beta.
    !> @param[in]
    !> BP         device pointer storing matrix B.
    !> @param[in]
    !> ldb       [int]
    !> specifies the leading dimension of B.
    !> @param[in, out]
    !> CP         device pointer storing matrix C.
    !> @param[in]
    !> ldc       [int]
    !> specifies the leading dimension of C.
    function hipblasSgeam(handle, transA, transB, m, n, alpha, AP, lda, beta, BP, ldb, CP, ldc) &
       result(Sgeam) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasSgeam")
#else
       bind(C, name="hipblasSgeam")
#endif
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
       integer(c_int), value :: transA
       integer(c_int), value :: transB
       integer(c_int), value :: m
       integer(c_int), value :: n
       real(c_float) :: alpha(*)
       real(c_float) :: AP(*)
       integer(c_int), value :: lda
       real(c_float) :: beta(*)
       real(c_float) :: BP(*)
       integer(c_int), value :: ldb
       real(c_float) :: CP(*)
       integer(c_int), value :: ldc
       integer(c_int) :: Sgeam
    end function hipblasSgeam

